import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

/* ── tiny inline icons (GitHub / Google) ── */
const GoogleIcon = () => (
  <svg className="w-5 h-5 mr-2" viewBox="0 0 24 24" fill="currentColor">
    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 01-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4" />
    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
  </svg>
);

const GitHubIcon = () => (
  <svg className="w-5 h-5 mr-2" viewBox="0 0 24 24" fill="currentColor">
    <path fillRule="evenodd" clipRule="evenodd" d="M12 2C6.477 2 2 6.484 2 12.017c0 4.425 2.865 8.18 6.839 9.504.5.092.682-.217.682-.483 0-.237-.008-.868-.013-1.703-2.782.605-3.369-1.343-3.369-1.343-.454-1.158-1.11-1.466-1.11-1.466-.908-.62.069-.608.069-.608 1.003.07 1.531 1.032 1.531 1.032.892 1.53 2.341 1.088 2.91.832.092-.647.35-1.088.636-1.338-2.22-.253-4.555-1.113-4.555-4.951 0-1.093.39-1.988 1.029-2.688-.103-.253-.446-1.272.098-2.65 0 0 .84-.27 2.75 1.026A9.564 9.564 0 0112 6.844c.85.004 1.705.115 2.504.337 1.909-1.296 2.747-1.027 2.747-1.027.546 1.379.202 2.398.1 2.651.64.7 1.028 1.595 1.028 2.688 0 3.848-2.339 4.695-4.566 4.943.359.309.678.92.678 1.855 0 1.338-.012 2.419-.012 2.747 0 .268.18.58.688.482A10.019 10.019 0 0022 12.017C22 6.484 17.522 2 12 2z" />
  </svg>
);

/* ── Floating workspace card (animated) ── */
const WorkspaceCard = ({ delay, top, left, children, extraStyle }) => (
  <div
    className={`absolute bg-slate-900/70 backdrop-blur-md border border-slate-800/80 rounded-2xl px-4 py-3 shadow-lg animate-float ${extraStyle ?? ""}`}
    style={{ top, left, animationDelay: `${delay}s` }}
  >
    {children}
  </div>
);

/* ── Left panel: illustration, floating cards, avatars ── */
const LeftPanel = () => (
  <div className="hidden lg:flex lg:w-1/2 relative bg-[#020617] overflow-hidden items-center justify-center">
    {/* Ambient glow */}
    <div className="absolute top-1/3 left-1/3 w-[500px] h-[500px] bg-violet-600/20 rounded-full blur-[120px]" />
    <div className="absolute bottom-1/4 right-1/4 w-[400px] h-[400px] bg-indigo-600/15 rounded-full blur-[100px]" />

    {/* Animated background particles */}
    <div className="absolute inset-0 overflow-hidden pointer-events-none">
      {[...Array(8)].map((_, i) => (
        <div
          key={i}
          className="absolute w-1 h-1 bg-white/20 rounded-full animate-drift"
          style={{
            left: `${Math.random() * 100}%`,
            top: `${Math.random() * 100}%`,
            animationDuration: `${6 + Math.random() * 6}s`,
            animationDelay: `${Math.random() * 5}s`,
          }}
        />
      ))}
    </div>

    {/* Floating workspace cards */}
    <WorkspaceCard delay={0} top="12%" left="10%">
      <div className="flex items-center gap-3">
        <div className="w-2.5 h-2.5 rounded-full bg-emerald-400 animate-pulse" />
        <span className="text-xs text-slate-300 font-medium">5 team members online</span>
      </div>
    </WorkspaceCard>

    <WorkspaceCard delay={1.2} top="22%" left="55%">
      <div className="flex items-center gap-3">
        <div className="w-8 h-8 rounded-full bg-violet-500 flex items-center justify-center text-white text-xs font-bold">TK</div>
        <div>
          <p className="text-xs text-slate-400">Task updated</p>
          <p className="text-sm text-white font-medium">Design system v2</p>
        </div>
      </div>
    </WorkspaceCard>

    <WorkspaceCard delay={2.5} top="52%" left="15%">
      <div className="flex items-start gap-3">
        <div className="w-8 h-8 rounded-lg bg-indigo-500 flex items-center justify-center text-white text-xs font-bold">📄</div>
        <div>
          <p className="text-xs text-slate-400">Shared document</p>
          <p className="text-sm text-white font-medium">Q1 roadmap draft</p>
        </div>
      </div>
    </WorkspaceCard>

    <WorkspaceCard delay={0.8} top="65%" left="50%">
      <div className="flex items-center gap-2">
        <div className="flex -space-x-2">
          {['A', 'B', 'C'].map((letter, i) => (
            <div key={i} className="w-7 h-7 rounded-full bg-slate-700 border-2 border-slate-900 flex items-center justify-center text-xs text-white font-semibold">{letter}</div>
          ))}
        </div>
        <span className="text-xs text-slate-400">typing...</span>
      </div>
    </WorkspaceCard>

    {/* Main illustration text */}
    <div className="relative z-10 text-center px-8">
      <h2 className="text-4xl lg:text-5xl font-bold text-white mb-4 tracking-tight">
        Work together <br />
        <span className="bg-gradient-to-r from-violet-400 to-indigo-400 bg-clip-text text-transparent">
          in real time.
        </span>
      </h2>
      <p className="text-slate-400 text-lg max-w-md mx-auto">
        Collaborate with your team anywhere, anytime.
      </p>

      {/* Floating avatars row */}
      <div className="mt-10 flex justify-center gap-1">
        {[...Array(6)].map((_, i) => (
          <div
            key={i}
            className="w-10 h-10 rounded-full border-2 border-slate-800 bg-gradient-to-br from-slate-600 to-slate-800 animate-float"
            style={{ animationDelay: `${i * 0.2}s`, backgroundImage: `url(https://i.pravatar.cc/40?img=${i + 10})`, backgroundSize: 'cover' }}
          />
        ))}
        <div className="w-10 h-10 rounded-full border-2 border-slate-800 bg-slate-700 flex items-center justify-center text-xs text-white font-semibold animate-float" style={{ animationDelay: '1.2s' }}>
          +12
        </div>
      </div>
    </div>
  </div>
);

/* ── Right panel: glassmorphism login card ── */
const RightPanel = () => {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: "", password: "" });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);
  const [globalError, setGlobalError] = useState("");
  const [rememberMe, setRememberMe] = useState(false);

  const validate = () => {
    const errs = {};
    if (!form.email) errs.email = "Email is required";
    else if (!/\S+@\S+\.\S+/.test(form.email)) errs.email = "Enter a valid email";
    if (!form.password) errs.password = "Password is required";
    return errs;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const errs = validate();
    if (Object.keys(errs).length) {
      setErrors(errs);
      return;
    }
    setLoading(true);
    setGlobalError("");
    const result = await login({ ...form, rememberMe });
    setLoading(false);
    if (result.success) {
      navigate("/");
    } else {
      setGlobalError(result.message);
    }
  };

  const handleSocialLogin = (provider) => {
    // placeholder – implement social auth later
    alert(`${provider} sign in coming soon`);
  };

  const set = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.value }));

  return (
    <div className="w-full lg:w-1/2 flex items-center justify-center bg-slate-950 px-4 py-12 lg:p-0">
      <div className="w-full max-w-md">
        {/* Logo + heading */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center gap-2.5 mb-4">
            <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-violet-500 to-indigo-600 flex items-center justify-center text-white font-bold text-lg shadow-lg shadow-violet-500/30">
              Z
            </div>
            <span className="text-white font-semibold text-xl tracking-tight">Zaalima</span>
          </div>
          <h1 className="text-2xl font-bold text-white mb-1">Welcome back</h1>
          <p className="text-slate-400 text-sm">Enter your workspace credentials</p>
        </div>

        {/* Glass card */}
        <div className="bg-slate-900/70 backdrop-blur-xl border border-slate-800 rounded-2xl p-8 shadow-2xl">
          {/* Social login buttons */}
          <div className="space-y-3 mb-6">
            <button
              type="button"
              onClick={() => handleSocialLogin("google")}
              className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-xl bg-white/5 border border-slate-700 text-white text-sm font-medium hover:bg-white/10 transition-all"
            >
              <GoogleIcon /> Continue with Google
            </button>
            <button
              type="button"
              onClick={() => handleSocialLogin("github")}
              className="w-full flex items-center justify-center gap-2 py-3 px-4 rounded-xl bg-white/5 border border-slate-700 text-white text-sm font-medium hover:bg-white/10 transition-all"
            >
              <GitHubIcon /> Continue with GitHub
            </button>
          </div>

          {/* Divider */}
          <div className="relative mb-6">
            <div className="absolute inset-0 flex items-center">
              <div className="w-full border-t border-slate-800"></div>
            </div>
            <div className="relative flex justify-center text-sm">
              <span className="px-3 bg-slate-900 text-slate-400">or continue with email</span>
            </div>
          </div>

          {/* Form */}
          <form onSubmit={handleSubmit}>
            {globalError && (
              <div className="mb-5 px-4 py-3 rounded-lg bg-red-500/10 border border-red-500/30 text-red-400 text-sm">
                {globalError}
              </div>
            )}

            <div className="mb-5">
              <label className="block text-sm font-medium text-slate-300 mb-1.5">Email</label>
              <input
                type="email"
                value={form.email}
                onChange={set("email")}
                placeholder="you@company.com"
                className={`w-full px-4 py-3 rounded-xl bg-slate-800/60 border text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-violet-500 focus:border-transparent transition-all ${errors.email ? "border-red-500" : "border-slate-700"
                  }`}
              />
              {errors.email && <p className="mt-1 text-sm text-red-400">{errors.email}</p>}
            </div>

            <div className="mb-5">
              <label className="block text-sm font-medium text-slate-300 mb-1.5">Password</label>
              <input
                type="password"
                value={form.password}
                onChange={set("password")}
                placeholder="••••••••"
                className={`w-full px-4 py-3 rounded-xl bg-slate-800/60 border text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-violet-500 focus:border-transparent transition-all ${errors.password ? "border-red-500" : "border-slate-700"
                  }`}
              />
              {errors.password && <p className="mt-1 text-sm text-red-400">{errors.password}</p>}
            </div>

            <div className="flex items-center justify-between mb-6">
              <label className="flex items-center gap-2 text-sm text-slate-400 cursor-pointer">
                <input
                  type="checkbox"
                  checked={rememberMe}
                  onChange={(e) => setRememberMe(e.target.checked)}
                  className="w-4 h-4 rounded border-slate-600 bg-slate-800 text-violet-500 focus:ring-violet-500 focus:ring-offset-0"
                />
                Remember me
              </label>
              <a href="/forgot-password" className="text-sm text-violet-400 hover:text-violet-300 transition-colors">
                Forgot password?
              </a>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full py-3 px-4 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 text-white font-semibold hover:from-violet-500 hover:to-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 shadow-lg shadow-violet-500/20 hover:shadow-violet-500/30"
            >
              {loading ? "Signing in…" : "Sign in"}
            </button>
          </form>
        </div>

        {/* Footer */}
        <div className="mt-6 text-center space-y-4">
          <p className="text-sm text-slate-400">
            No account?{" "}
            <Link to="/register" className="text-violet-400 hover:text-violet-300 font-medium transition-colors">
              Create one
            </Link>
          </p>
          <div className="flex items-center justify-center gap-2 text-xs text-slate-500">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />
            </svg>
            Enterprise-grade security
          </div>
        </div>
      </div>
    </div>
  );
};

/* ── Main LoginPage component (combines left + right) ── */
export const LoginPage = () => (
  <div className="min-h-screen flex bg-[#020617]">
    {/* Custom keyframes for particles and floating cards */}
    <style>{`
      @keyframes float {
        0%, 100% { transform: translateY(0px) rotate(0deg); }
        50% { transform: translateY(-12px) rotate(1deg); }
      }
      @keyframes drift {
        0% { transform: translate(0, 0) scale(1); opacity: 0.3; }
        50% { transform: translate(20px, -20px) scale(1.5); opacity: 0.7; }
        100% { transform: translate(0, 0) scale(1); opacity: 0.3; }
      }
      .animate-float {
        animation: float 6s ease-in-out infinite;
      }
      .animate-drift {
        animation: drift linear infinite;
      }
    `}</style>

    <LeftPanel />
    <RightPanel />
  </div>
);

export default LoginPage;
